best=None
for w in np.linspace(0.05,4,800):
    for basis in ['P','1/P']:
        B=[np.ones_like(P),P,P**2,np.sin(w*t),np.cos(w*t)]
        if basis=='1/P': B=[np.ones_like(P),P,P**2,np.sin(w*t)/P,np.cos(w*t)/P]
        A=np.column_stack(B)
        c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
        nm=np.mean((A@c-dP_dt)**2)/np.var(dP_dt)
        if best is None or nm<best[0]: best=(nm,w,basis,c)
print(best)
